import re,sys,json,glob,collections
S=sys.argv[1]
rows={}
for line in open('docs/architecture/requirements-traceability.md',encoding='utf-8'):
    m=re.match(r'\| (TR-[a-z]+-\d{3}) \| (.*) \| ([^|]*) \| ([^|]*) \| ([^|]*) \| ([^|]*) \|\s*$',line)
    if m and m.group(1) not in rows:
        rows[m.group(1)]=dict(id=m.group(1),req=m.group(2),domain=m.group(3).strip(),planned=m.group(4).strip(),cov=m.group(5).strip(),status=m.group(6).strip())
print(len(rows))
cited=collections.defaultdict(set)
for f in sorted(glob.glob('docs/architecture/adr-*.md')):
    n=f.split('adr-')[1][:4]
    for t in set(re.findall(r'TR-[a-z]+-\d{3}',open(f,encoding='utf-8').read())): cited[t].add(n)
found=set(['%04d'%i for i in range(1,11)])
cand={}
for t,r in rows.items():
    pl=set(re.findall(r'ADR-(\d{4})',r['planned']))
    c=(pl&found)|cited.get(t,set())
    if c: cand[t]=sorted(c)
print('candidates',len(cand))
print('cited not in index',[t for t in cited if t not in rows])
cnt=collections.Counter(a for v in cand.values() for a in v); print(sorted(cnt.items()))
json.dump(dict(rows=rows,cited={k:sorted(v) for k,v in cited.items()},cand=cand),open(S+'/base.json','w'),indent=1)
EOF
