  name: 'gdd-sync-confirm',
  description: 'Consistency-check the 21 GDDs changed by the Foundation GDD sync, fix cross-GDD leftovers per file, then a lean design review of each changed GDD',
  phases: [
    { title: 'Scan', detail: 'one Sonnet scanner per changed GDD: what changed, where else it is stated', model: 'sonnet' },
    { title: 'Fix', detail: 'one Sonnet fixer per file with leftovers', model: 'sonnet' },
    { title: 'Review', detail: 'lean design review per changed GDD', model: 'sonnet' },
  ],
}

const ROOT = 'D:/the-synaptic-sea-2d'
const BASE = `Work in ${ROOT}. GDDs and registries are large; a hook refuses whole-file reads over 40 KB, so Grep and Read ranges. Never run git except the one read-only command a step allows.`
const SCAN = { type: 'object', properties: {
  gdd: { type: 'string' },
  changes: { type: 'array', items: { type: 'string' } },
  leftovers: { type: 'array', items: { type: 'object', properties: {
    target_file: { type: 'string' }, line: { type: 'integer' }, stale_text: { type: 'string' }, should_say: { type: 'string' }, why: { type: 'string' } },
    required: ['target_file', 'stale_text', 'should_say', 'why'] } },
}, required: ['gdd', 'changes', 'leftovers'] }
const FIX = { type: 'object', properties: {
  file: { type: 'string' }, fixed: { type: 'integer' }, declined: { type: 'array', items: { type: 'object', properties: { stale_text: { type: 'string' }, reason: { type: 'string' } }, required: ['stale_text', 'reason'] } },
  registry_requests: { type: 'array', items: { type: 'object', properties: { registry: { type: 'string' }, entry: { type: 'string' }, change: { type: 'string' } }, required: ['registry', 'entry', 'change'] } },
}, required: ['file', 'fixed', 'declined', 'registry_requests'] }
const REVIEW = { type: 'object', properties: {
  gdd: { type: 'string' }, verdict: { type: 'string', enum: ['APPROVED', 'NEEDS REVISION'] },
  blockers: { type: 'array', items: { type: 'object', properties: { where: { type: 'string' }, issue: { type: 'string' }, fix: { type: 'string' } }, required: ['where', 'issue', 'fix'] } },
  advisories: { type: 'array', items: { type: 'string' } },
  log_entry: { type: 'string' },
}, required: ['gdd', 'verdict', 'blockers', 'advisories', 'log_entry'] }

phase('Scan')
const scans = await parallel(args.gdds.map(g => () => agent(`${BASE} You may run exactly: git diff -- ${g}

${g} was just edited to sync it with the Proposed Foundation ADRs (docs/architecture/adr-0001..0010) — 2026-10-29 amendments. Read the diff and list each substantive change (renamed API or signature, changed constant/value, changed rule, new file name, ownership moved). Then for EACH change grep the other GDDs (design/gdd/*.md, excluding reviews/), design/registry/entities.yaml and docs/architecture/architecture.md for places that still state the OLD form, and report each as a leftover with target_file, line, the stale text (short exact quote), what it should say and why. Only report real contradictions with the new text, not wording differences. Do not edit anything.`,
  { label: `scan:${g.split('/').pop()}`, phase: 'Scan', schema: SCAN, model: 'sonnet', effort: 'medium' })))

const byFile = {}
for (const s of scans.filter(Boolean)) for (const l of s.leftovers) {
  const k = l.target_file.replace(/^\.?\/?/, '')
  ;(byFile[k] = byFile[k] || []).push({ ...l, source: s.gdd })
}
const targets = Object.keys(byFile)
log(`${targets.length} files with leftovers; ${targets.reduce((n, k) => n + byFile[k].length, 0)} leftovers`)

phase('Fix')
