const fixes = await parallel(targets.filter(f => !REG.has(f)).map(f => () => agent(`${BASE}

Edit ONLY ${f}. These places were reported as still stating a form that another document has just changed to match a Proposed ADR (user ruling: the ADR wins):
${JSON.stringify(byFile[f], null, 1).slice(0, 12000)}
For each: verify against the source GDD's current text and the ADR it cites (grep), then fix the stale text in ${f} (minimal edit; GDDs mark the change with an italic "*(Amended 2026-10-29 — ADR-00NN sync)*" note matching the file's existing amendment-note format). Decline with a reason if the report is wrong. If a registry entry needs to change, return a registry_request instead of editing a registry.`,
  { label: `fix:${f.split('/').pop()}`, phase: 'Fix', schema: FIX, model: 'sonnet', effort: 'medium' })))

phase('Review')
const reviews = await parallel(args.gdds.map(g => () => agent(`${BASE} You may run exactly: git diff -- ${g}

Lean confirming design review of ${g} after the 2026-10-29 Foundation ADR sync (it was APPROVED before; see design/gdd/reviews/<slug>-review-log.md for the last review). Review ONLY what changed (the diff) and its knock-on effects inside this GDD: internal consistency (rules vs formulas vs edge cases vs acceptance criteria vs tuning knobs), every acceptance criterion still testable and consistent with the changed rule, no dangling references (rule ids, ADR sections, constants), design intent preserved. Blockers are defects that would mislead an implementer; anything else is an advisory. Do not edit. Return verdict, blockers (where/issue/fix), advisories and a log_entry: a markdown section for the review log, headed "## Review — 2026-10-29 — Foundation ADR sync (lean confirming)", with verdict, scope, blockers and advisories (under 25 lines).`,
  { label: `review:${g.split('/').pop()}`, phase: 'Review', schema: REVIEW, model: 'sonnet', effort: 'high' })))

return {
  scans: scans.map((s, i) => s || { gdd: args.gdds[i], failed: true }),
  registry_leftovers: targets.filter(f => REG.has(f)).map(f => ({ file: f, items: byFile[f] })),
  fixes: fixes.filter(Boolean),
  reviews: reviews.map((r, i) => r || { gdd: args.gdds[i], failed: true }),
}

