export const meta = {
  name: 'foundation-adrs',
  description: 'Author ADR-0004/0005/0006/0008/0009/0010 in parallel, joint engine + TD-ADR review, revise, cross-ADR check, serial registry merge',
  phases: [
    { title: 'Author', detail: '6 Sonnet authors, one ADR file each' },
    { title: 'Review', detail: 'godot-specialist (Sonnet) + technical-director TD-ADR (Opus) over all six' },
    { title: 'Revise', detail: '6 Sonnet revisers apply findings' },
    { title: 'Confirm', detail: 'cross-ADR consistency check' },
    { title: 'Registry', detail: 'serial registry merge + decision log' },
  ],
}

const ADRS = args.adrs
const SIBLINGS = ADRS.map(a => `ADR-${a.id} ${a.title} (decides: ${a.decides})`).join('\n')
const SKILL = 'C:/Users/dasbl/.claude/skills/architecture-decision'
const ROOT = 'D:/the-synaptic-sea-2d'

const AUTHOR_SCHEMA = {
  type: 'object',
  properties: {
    adr_id: { type: 'string' },
    path: { type: 'string' },
    summary: { type: 'string' },
    depends_on: { type: 'array', items: { type: 'string' } },
    registry_candidates: { type: 'array', items: { type: 'object', properties: {
      section: { type: 'string', enum: ['state_ownership', 'interfaces', 'performance_budgets', 'api_decisions', 'forbidden_patterns', 'referenced_by_update'] },
      name: { type: 'string' }, entry_yaml: { type: 'string' } }, required: ['section', 'name', 'entry_yaml'] } },
    gdd_sync: { type: 'array', items: { type: 'object', properties: { file: { type: 'string' }, old: { type: 'string' }, new: { type: 'string' } }, required: ['file', 'old', 'new'] } },
    decisions: { type: 'array', items: { type: 'object', properties: { point: { type: 'string' }, chosen: { type: 'string' }, reason: { type: 'string' } }, required: ['point', 'chosen', 'reason'] } },
    cross_adr_assumptions: { type: 'array', items: { type: 'object', properties: { other_adr: { type: 'string' }, assumption: { type: 'string' } }, required: ['other_adr', 'assumption'] } },
    open_questions: { type: 'array', items: { type: 'string' } },
  },
  required: ['adr_id', 'path', 'summary', 'depends_on', 'registry_candidates', 'gdd_sync', 'decisions', 'cross_adr_assumptions', 'open_questions'],
}

const REVIEW_SCHEMA = {
  type: 'object',
  properties: {
    reviews: { type: 'array', items: { type: 'object', properties: {
      adr_id: { type: 'string' }, verdict: { type: 'string' },
      findings: { type: 'array', items: { type: 'object', properties: {
        id: { type: 'string' }, severity: { type: 'string' }, blocking: { type: 'boolean' }, text: { type: 'string' }, amendment: { type: 'string' } },
        required: ['id', 'severity', 'blocking', 'text', 'amendment'] } } },
      required: ['adr_id', 'verdict', 'findings'] } },
    cross_adr: { type: 'array', items: { type: 'object', properties: {
      id: { type: 'string' }, adrs: { type: 'array', items: { type: 'string' } }, owner_adr: { type: 'string' },
      severity: { type: 'string' }, text: { type: 'string' }, amendment: { type: 'string' } },
      required: ['id', 'adrs', 'owner_adr', 'severity', 'text', 'amendment'] } },
  },
  required: ['reviews', 'cross_adr'],
}

const REVISE_SCHEMA = {
  type: 'object',
  properties: {
    adr_id: { type: 'string' },
    applied: { type: 'array', items: { type: 'string' } },
    declined: { type: 'array', items: { type: 'object', properties: { id: { type: 'string' }, reason: { type: 'string' } }, required: ['id', 'reason'] } },
    registry_candidates: AUTHOR_SCHEMA.properties.registry_candidates,
    gdd_sync: AUTHOR_SCHEMA.properties.gdd_sync,
    decisions: AUTHOR_SCHEMA.properties.decisions,
    open_questions: { type: 'array', items: { type: 'string' } },
  },
  required: ['adr_id', 'applied', 'declined', 'registry_candidates', 'gdd_sync', 'decisions', 'open_questions'],
}

const CONFIRM_SCHEMA = {
  type: 'object',
  properties: {
    residual: { type: 'array', items: { type: 'object', properties: { adrs: { type: 'array', items: { type: 'string' } }, severity: { type: 'string' }, text: { type: 'string' } }, required: ['adrs', 'severity', 'text'] } },
    blocking_items_unapplied: { type: 'array', items: { type: 'string' } },
    notes: { type: 'string' },
  },
  required: ['residual', 'blocking_items_unapplied', 'notes'],
}

const authorPrompt = (a) => `You are authoring ONE Architecture Decision Record for the Godot 4.7.2 / GDScript game project at ${ROOT}: ADR-${a.id} "${a.title}". Write it to ${ROOT}/docs/architecture/adr-${a.id}-${a.slug}.md (exact path). Status must be Proposed. Date 2026-10-28.

FOLLOW THE SKILL. Read ${SKILL}/SKILL.md and its reference files ${SKILL}/references/1-engine-context.md, 3-gather-context.md, 4-decide.md and 5-generate.md, and follow Steps 1 to 5 with these run-specific overrides:
- Resolved config: review_mode full, workflow full, docs.density thorough (full prose with trade-offs in Decision, Alternatives, Consequences), automation AUTONOMOUS: never call AskUserQuestion; derive assumptions and design choices yourself, take the recommended option, and record every decision point in your return value's decisions list.
- Do NOT spawn the engine specialist or technical-director (Steps 5.5/5.6): the orchestrator runs those reviews jointly across all six ADRs afterwards. Put "Review Log: pending (joint review)" at the end of the ADR.
- Do NOT write docs/registry/architecture.yaml, any GDD, architecture.md, tr-*.md, the decision log or any file other than your own ADR. Return registry candidates and GDD sync items (Step 5.7 naming inconsistencies) in your return value instead. Never commit.
- Decision Makers: "Claude (author), running under modes.automation: autonomous (project.yaml); decisions logged for the user's review; the user has not yet reviewed this ADR." Do not attribute decisions to the user.

YOUR SCOPE (from docs/architecture/architecture.md, Required ADRs table): absorbs ${a.absorbs}; decides: ${a.decides}.
Run-specific notes: ${a.notes}

CONTEXT TO READ (by section; the docs are large, follow coordination rule 6: grep headings, then bounded reads):
- docs/registry/architecture.yaml (binding stances: do not contradict; surface conflicts in open_questions).
- docs/architecture/architecture.md: sections "Required ADRs", "Spikes that gate ADRs", "Open Questions", "Engine Knowledge Gap Summary", "System Layer Map", "Data Flow", "API Boundaries", and anything grep finds for ADR-${a.id}.
- docs/architecture/tr-baseline.md: every row whose last column cites ADR-${a.id} (grep "ADR-${a.id}"); your GDD Requirements Addressed table must cover them by TR-ID, and rows that are only loaded/checked but owned elsewhere go in a separate "owned elsewhere" sub-table.
- docs/architecture/architecture-review-2026-10-28.md, grep for ADR-${a.id}.
- Existing ADRs ADR-0001, 0002, 0003 (Proposed) and ADR-0007 (Proposed): read their Summary, Decision and Key Interfaces where your scope touches them. ADR-0007 (docs/architecture/adr-0007-static-content-data-pipeline-and-stable-type-ids.md) is the format and density exemplar, including its numbered sub-decisions, Implementation Guidelines as must/must never, Validation Criteria, Open Questions and Review Log.
- The GDDs the TR rows cite, only the cited rules (grep the rule id, e.g. "^\\*\\*CR-9", then read that range). GDDs are ~500 KB each: never read one whole.
- docs/engine-reference/godot/ (VERSION.md, breaking-changes.md, deprecated-apis.md, current-best-practices.md, and modules/*.md relevant to your domain). Mark every engine claim that the reference does not source as UNVERIFIED and name the spike or probe that settles it.
- You MAY probe small engine facts with the installed editor: "C:/Users/dasbl/Documents/Godot/Godot_v4.7.2-stable_mono_win64_console.exe" --headless --script <file> run from a scratch directory OUTSIDE the repo (C:/Users/dasbl/AppData/Local/Temp/claude/adr-probes/${a.id}/). Record probe results as "probed 2026-10-28" in Engine Compatibility. Never create files inside the repo other than your ADR.

PARALLEL SIBLINGS. These Foundation ADRs are being authored at the same time by other agents; do not decide their scope, reference them by number as forward references, and list every assumption you make about a sibling in cross_adr_assumptions:
${SIBLINGS}
Already written (Proposed): ADR-0001 kernel tick driver and frame order; ADR-0002 authority model and command pipeline; ADR-0003 state-block registry, write discipline and owner-callable contract; ADR-0007 static content data pipeline and stable type IDs.

Return the structured result: path, a 2-sentence summary, depends_on ADR ids, registry_candidates (entry_yaml in the registry's exact layout, fields two columns past the dash, status: active with a comment that the ADR is Proposed), gdd_sync items, decisions, cross_adr_assumptions, open_questions.`

phase('Author')
const authored = (await parallel(ADRS.map(a => () =>
  agent(authorPrompt(a), { label: `author:ADR-${a.id}`, phase: 'Author', schema: AUTHOR_SCHEMA, model: 'sonnet', effort: 'high' })
))).filter(Boolean)
log(`Authored ${authored.length}/${ADRS.length} ADRs: ${authored.map(r => r.adr_id).join(', ')}`)
if (authored.length < ADRS.length) log(`MISSING authors: ${ADRS.filter(a => !authored.some(r => r.adr_id.includes(a.id))).map(a => a.id).join(', ')}`)

const fileList = authored.map(r => `- ${r.adr_id}: ${r.path}`).join('\n')
const assumptions = authored.map(r => `${r.adr_id} assumes: ${r.cross_adr_assumptions.map(x => `[${x.other_adr}] ${x.assumption}`).join(' | ') || 'none'}`).join('\n')

phase('Review')
const [engine, td] = await parallel([
  () => agent(`Review-only task: do NOT edit or write any file. Validate these newly drafted ADRs for the Godot 4.7.2 GDScript project at ${ROOT} against the pinned engine:
${fileList}
Engine reference: ${ROOT}/docs/engine-reference/godot/ (VERSION.md, breaking-changes.md, deprecated-apis.md, current-best-practices.md, modules/). For each ADR: (1) is the approach idiomatic for 4.7.2; (2) any API or pattern deprecated, changed after your training cutoff, or simply wrong (wrong signatures, things that will not compile, e.g. const of constructed objects, packed arrays passed by reference, typed-return override rule 4.7, member names clashing with Object methods); (3) engine gotchas the draft misses. Be concrete and give a confidence per claim. You may probe facts headless with "C:/Users/dasbl/Documents/Godot/Godot_v4.7.2-stable_mono_win64_console.exe" --headless --script <file> from a scratch dir OUTSIDE the repo (C:/Users/dasbl/AppData/Local/Temp/claude/adr-probes/engine-review/). Also flag engine-level contradictions BETWEEN the ADRs in cross_adr. Return findings per ADR with ids E1, E2... (blocking=true for wrong API / will not compile / incompatible), each with a concrete amendment; cross_adr items with an owner_adr that should change.`,
    { label: 'review:engine', phase: 'Review', schema: REVIEW_SCHEMA, model: 'sonnet', effort: 'high', agentType: 'godot-specialist' }),
  () => agent(`Review-only task: do NOT edit or write any file. Run gate TD-ADR (definition and verdict format: ${ROOT}/.claude/docs/director-gates/td-adr.md) on EACH of these six newly drafted, parallel-authored Foundation ADRs (Proposed, Godot 4.7.2, GDScript, review mode full), AND review them as a set for cross-ADR coherence, because their authors could not see each other's drafts:
${fileList}
Authors' stated assumptions about each other:
${assumptions}
Binding context: ${ROOT}/docs/registry/architecture.yaml; already-written Proposed ADRs ADR-0001, 0002, 0003 and ADR-0007 in ${ROOT}/docs/architecture/; ${ROOT}/docs/architecture/architecture.md (System Layer Map, Data Flow, Required ADRs, Spikes, Open Questions); TR rows in docs/architecture/tr-baseline.md. Read docs by section (grep headings, bounded reads).
For each ADR: verdict APPROVE / CONCERNS / REJECT with findings T1, T2... (severity, blocking true when it must change before Accept, concrete amendment). Check: contradictions with registry stances and ADR-0001/2/3/7; scope overlap or gaps between the six (who owns what); right-sizing for a solo/small-team MVP; traceability of the ADR's TR rows; spike gating stated honestly. In cross_adr list every inconsistency between two or more of the six (e.g. dirty-key layout vs notification vs subscriber contract; canonical encoding vs save container vs ADR-0007 hash input; lint ownership in ADR-0010 vs rules other ADRs assign to it; fault-domain usage), with the single owner_adr that should change and the exact amendment.`,
    { label: 'review:TD-ADR', phase: 'Review', schema: REVIEW_SCHEMA, model: 'opus', effort: 'high', agentType: 'technical-director' }),
])
if (!engine) log('Engine review FAILED (null) — revisers proceed on TD findings only')
if (!td) log('TD-ADR review FAILED (null) — revisers proceed on engine findings only')

const findingsFor = (rev, id) => {
  if (!rev) return 'review unavailable'
  const r = rev.reviews.find(x => x.adr_id.includes(id))
  const own = r ? `verdict ${r.verdict}\n` + r.findings.map(f => `${f.id} [${f.severity}${f.blocking ? ', BLOCKING' : ''}] ${f.text}\n  amendment: ${f.amendment}`).join('\n') : 'no per-ADR findings'
  const cross = rev.cross_adr.filter(c => c.adrs.some(x => x.includes(id)) || c.owner_adr.includes(id))
    .map(c => `${c.id} [${c.severity}] owner ${c.owner_adr}; involves ${c.adrs.join(', ')}: ${c.text}\n  amendment: ${c.amendment}`).join('\n')
  return own + (cross ? `\nCross-ADR items involving you:\n${cross}` : '')
}

phase('Revise')
const revised = (await parallel(authored.map(r => () => {
  const id = (r.adr_id.match(/\d{4}/) || [''])[0]
  return agent(`You are revising ${r.adr_id} at ${r.path} (project ${ROOT}, Godot 4.7.2 GDScript) after a joint engine review and TD-ADR review of six parallel-authored Foundation ADRs. Autonomous mode: the recommended action is "Revise flagged items". Apply every BLOCKING finding; apply non-blocking findings unless clearly wrong for this ADR (then decline with a reason). For cross-ADR items: if owner_adr is ${r.adr_id}, change your ADR; if another ADR owns the change, make sure your ADR's text is consistent with the stated amendment (adjust your references and assumptions) but do not take over the other ADR's decision. Read the ADR first; edit only this file. Keep Status Proposed. Replace the "Review Log: pending" line with a Review Log section dated 2026-10-28 listing each finding id and what was done, like ADR-0007's Review Log. Keep docs.density thorough. Do not edit the registry, GDDs or any other file; never commit.

ENGINE REVIEW (godot-specialist):
${findingsFor(engine, id)}

TD-ADR REVIEW (technical-director):
${findingsFor(td, id)}

Your original registry candidates (update them to match the revised ADR and return the final set):
${JSON.stringify(r.registry_candidates)}
Your original GDD sync items (return the final set):
${JSON.stringify(r.gdd_sync)}
Return applied ids, declined ids with reasons, final registry_candidates, final gdd_sync, any new decisions, and open_questions.`,
    { label: `revise:${r.adr_id}`, phase: 'Revise', schema: REVISE_SCHEMA, model: 'sonnet', effort: 'high' })
}))).filter(Boolean)
log(`Revised ${revised.length}/${authored.length}`)

phase('Confirm')
const blockingList = [engine, td].filter(Boolean).flatMap(rv => [
  ...rv.reviews.flatMap(x => x.findings.filter(f => f.blocking).map(f => `${x.adr_id} ${f.id}: ${f.text}`)),
  ...rv.cross_adr.map(c => `${c.id} (owner ${c.owner_adr}): ${c.text} -> ${c.amendment}`),
])
const confirm = await agent(`Review-only: do NOT edit any file. Six Foundation ADRs were just revised in parallel:
${fileList}
Check two things and report: (1) for each blocking finding and cross-ADR item below, is it actually applied in the current file text (list unapplied ones in blocking_items_unapplied, with the ADR id); (2) residual inconsistencies BETWEEN the six ADRs and against ADR-0001/0002/0003/0007 and docs/registry/architecture.yaml as they now stand (interface names, ownership, dependency tables, layering, fault domains, who owns which lint). Read by section; be concrete with quotes.
Items to verify:
${blockingList.join('\n')}`,
  { label: 'confirm:cross-ADR', phase: 'Confirm', schema: CONFIRM_SCHEMA, model: 'sonnet', effort: 'high' })

phase('Registry')
const candidates = revised.map(r => ({ adr: r.adr_id, items: r.registry_candidates }))
const decisions = [
  ...authored.map(r => ({ adr: r.adr_id, stage: 'author', items: r.decisions })),
  ...revised.map(r => ({ adr: r.adr_id, stage: 'revise', items: r.decisions, applied: r.applied, declined: r.declined })),
]
const registryReport = await agent(`You are the single serial writer for two shared files in ${ROOT}. Autonomous mode: the user's standing instruction is to apply registry updates (as was done for ADR-0007).
(1) Append these registry candidates to docs/registry/architecture.yaml. Follow the file's header LAYOUT rules exactly (block lists, dash at column 2, fields two columns past the dash, quote values containing ": "). Before each edit read the current file; append each new entry AFTER the last existing entry of its section (state_ownership, interfaces, performance_budgets, api_decisions, forbidden_patterns), before that section's "# Example:" comment block. For section referenced_by_update, add the ADR path to the named existing entry's referenced_by list only. Never modify or delete other existing fields. Skip a candidate that duplicates an existing entry name or another candidate (merge into one entry instead, listing both ADRs in referenced_by) and report it. Then run: bash .claude/scripts/registry.sh validate  and also  python -c "import yaml;yaml.safe_load(open('docs/registry/architecture.yaml',encoding='utf-8'))"  and fix any layout error you introduced.
Candidates: ${JSON.stringify(candidates)}
(2) Append to production/session-logs/decision-log.md (append only, never rewrite) one section per ADR in the existing format: "## 2026-10-28 — architecture-decision (ADR-NNNN, foundation-adrs workflow)" then for each decision "**Decision point:** ... / **Options considered:** ... / **Chosen:** ... / **Reason:** ... / **Category:** architecture", plus one entry for the joint review ("Revise flagged items", applied ids, declined ids with reasons) and one for the registry update.
Decisions: ${JSON.stringify(decisions)}
Do not edit any other file. Never commit. Return a short plain-text report: entries added per section, merged duplicates, validate output, decision-log sections appended.`,
  { label: 'registry+log', phase: 'Registry', model: 'sonnet', effort: 'medium' })

return {
  authored: authored.map(r => ({ adr: r.adr_id, path: r.path, summary: r.summary, depends_on: r.depends_on })),
  verdicts: {
    engine: engine ? engine.reviews.map(x => ({ adr: x.adr_id, verdict: x.verdict, blocking: x.findings.filter(f => f.blocking).length, total: x.findings.length })) : null,
    td: td ? td.reviews.map(x => ({ adr: x.adr_id, verdict: x.verdict, blocking: x.findings.filter(f => f.blocking).length, total: x.findings.length })) : null,
    cross_adr_count: (engine ? engine.cross_adr.length : 0) + (td ? td.cross_adr.length : 0),
  },
  revised: revised.map(r => ({ adr: r.adr_id, applied: r.applied.length, declined: r.declined, open_questions: r.open_questions })),
  gdd_sync: revised.map(r => ({ adr: r.adr_id, items: r.gdd_sync })),
  confirm,
  registryReport,
}

