const path = a => `${ROOT}/docs/architecture/adr-${a.id}-${a.slug}.md`

const AUTHOR = { type: 'object', properties: {
  adr_id: { type: 'string' }, path: { type: 'string' }, summary: { type: 'string' },
  depends_on: { type: 'array', items: { type: 'string' } },
  registry_candidates: { type: 'array', items: { type: 'object', properties: { section: { type: 'string', enum: ['state_ownership', 'interfaces', 'performance_budgets', 'api_decisions', 'forbidden_patterns', 'referenced_by_update'] }, name: { type: 'string' }, entry_yaml: { type: 'string' } }, required: ['section', 'name', 'entry_yaml'] } },
