  cross_adr_assumptions: { type: 'array', items: { type: 'object', properties: { other_adr: { type: 'string' }, assumption: { type: 'string' } }, required: ['other_adr', 'assumption'] } },
  tr_coverage: { type: 'object', properties: { covered: { type: 'integer' }, partial: { type: 'integer' }, owned_elsewhere: { type: 'integer' } }, required: ['covered', 'partial', 'owned_elsewhere'] },
  open_questions: { type: 'array', items: { type: 'string' } },
}, required: ['adr_id', 'path', 'summary', 'depends_on', 'registry_candidates', 'gdd_sync', 'foundation_asks', 'decisions', 'cross_adr_assumptions', 'tr_coverage', 'open_questions'] }
const REVIEW = { type: 'object', properties: {
  adr_id: { type: 'string' }, verdict: { type: 'string' },
