}, required: ['adr_id', 'applied', 'declined', 'registry_candidates', 'gdd_sync', 'decisions', 'open_questions'] }
const CONFIRM = { type: 'object', properties: {
  unapplied: { type: 'array', items: { type: 'string' } },
  residual: { type: 'array', items: { type: 'object', properties: { adrs: { type: 'array', items: { type: 'string' } }, severity: { type: 'string' }, text: { type: 'string' } }, required: ['adrs', 'severity', 'text'] } },
  notes: { type: 'string' },
}, required: ['unapplied', 'residual', 'notes'] }

const authorPrompt = (a, prior) => `You are authoring ONE Architecture Decision Record for the Godot 4.7.2 / GDScript game project at ${ROOT}: ADR-${a.id} "${a.title}". Write it to ${path(a)} (exact path). Status Proposed. Date 2026-10-29.

FOLLOW THE SKILL: read ${SKILL}/SKILL.md and ${SKILL}/references/1-engine-context.md, 3-gather-context.md, 4-decide.md, 5-generate.md and follow Steps 1-5 with these overrides:
- Config: review_mode full, workflow full, docs.density thorough, automation AUTONOMOUS: never call AskUserQuestion; take the recommended option and record every decision point in decisions.
- Do NOT run the engine-specialist or technical-director steps (5.5/5.6): the orchestrator reviews afterwards. End the ADR with "## Review Log" containing "pending (core-adrs workflow review)".
- Write ONLY your ADR file. Do not edit the registry, GDDs, architecture.md, tr-*.md, the traceability index, the decision log, other ADRs. Return registry candidates, GDD sync items and asks to Foundation ADRs instead. Never run git.
- Decision Makers: "Claude (author), running under modes.automation: autonomous (project.yaml); decisions logged for the user's review; the user has not yet reviewed this ADR."

SCOPE (docs/architecture/architecture.md § Required ADRs, Core table): absorbs ${a.absorbs}; decides: ${a.decides}. Notes: ${a.notes}

CONTEXT (docs are large; grep headings then bounded reads; a hook refuses whole-file reads over 40 KB):
- Requirements: grep "ADR-${a.id}" in docs/architecture/requirements-traceability.md (Planned ADR column, including rows re-tagged 2026-10-29). Your "## GDD Requirements Addressed" table must cover every one by TR-ID (registry text in docs/architecture/tr-registry.yaml); rows only loaded/checked here but decided elsewhere go in an "owned elsewhere" sub-table. Report counts in tr_coverage.
- Foundation ADRs (binding; do not contradict, build on their interfaces): ${FOUND}. Read Summary, Decision, Key Interfaces and Implementation Guidelines where your scope touches them. Exemplar for format and density: docs/architecture/adr-0007-static-content-data-pipeline-and-stable-type-ids.md. If you need a Foundation ADR changed, put it in foundation_asks; do not work around it silently.
- docs/registry/architecture.yaml (binding stances) and design/registry/entities.yaml (constants: cite names, never retype values).
- The GDDs your TR rows cite: only the cited rules (grep the rule id, e.g. "^\\*\\*LS-3", then read that range). GDD ADR-candidate notes for what you absorb (grep "${a.absorbs.split(',')[0].trim()}").
- docs/architecture/architecture.md: Required ADRs, Spikes that gate ADRs, Open Questions, System Layer Map, Data Flow, API Boundaries, Interface types still to define.
- docs/engine-reference/godot/ (VERSION.md, breaking-changes.md, deprecated-apis.md, current-best-practices.md, relevant modules/*.md). Mark every unsourced engine claim UNVERIFIED and name the spike or probe. You MAY probe small engine facts: "${GODOT}" --headless --script <file> from C:/Users/dasbl/AppData/Local/Temp/claude/adr-probes/${a.id}/ (outside the repo); record as "probed 2026-10-29".
SIBLINGS in this Core tier (do not decide their scope; reference them by number; list every assumption about them in cross_adr_assumptions):
${ALL}
${prior ? `Already drafted in earlier waves (read the parts you depend on; they are drafts, unreviewed):\n${prior}` : 'You are in wave A: the other Core ADRs are not written yet.'}
Return the structured result.`

const authored = []
for (const wave of ['A', 'B', 'C']) {
  phase('Author')
  const prior = authored.map(r => `- ${r.adr_id}: ${r.path} — ${r.summary}`).join('\n')
  const res = await parallel(ADRS.filter(a => a.wave === wave).map(a => () =>
    agent(authorPrompt(a, prior), { label: `author:ADR-${a.id}`, phase: 'Author', schema: AUTHOR, model: 'sonnet', effort: 'high' })))
  res.forEach((r, i) => { if (r) authored.push(r); else log(`AUTHOR FAILED: ADR-${ADRS.filter(a => a.wave === wave)[i].id}`) })
  log(`wave ${wave}: ${res.filter(Boolean).length} authored`)
