export const meta = {
  name: 'core-adrs',
  description: 'Author Core ADR-0011..0019 and ADR-0034 in three dependency waves (Sonnet), per-ADR engine (Sonnet) and TD-ADR (Opus) reviews, Opus cross-ADR adjudication, Sonnet revisers, confirm, serial registry + decision log',
  phases: [
    { title: 'Author', detail: 'Sonnet authors in waves A, B, C', model: 'sonnet' },
    { title: 'Review', detail: 'per-ADR godot-specialist (Sonnet) + technical-director TD-ADR (Opus)' },
    { title: 'Adjudicate', detail: 'one Opus cross-ADR ruling pass', model: 'opus' },
    { title: 'Revise', detail: 'Sonnet revisers apply rulings', model: 'sonnet' },
    { title: 'Confirm', detail: 'Sonnet cross-ADR confirm', model: 'sonnet' },
    { title: 'Registry', detail: 'serial registry merge + decision log', model: 'sonnet' },
  ],
}

const ROOT = 'D:/the-synaptic-sea-2d'
const SKILL = 'C:/Users/dasbl/.claude/skills/architecture-decision'
const GODOT = 'C:/Users/dasbl/Documents/Godot/Godot_v4.7.2-stable_mono_win64_console.exe'
const ADRS = args.adrs
const ALL = ADRS.map(a => `ADR-${a.id} ${a.title} (wave ${a.wave}; decides: ${a.decides})`).join('\n')
const FOUND = 'ADR-0001 tick driver/frame order; ADR-0002 authority/command pipeline; ADR-0003 block registry/owner contract; ADR-0004 change notification/dirty keys; ADR-0005 determinism/keyed RNG/encoding/hashing; ADR-0006 save container/generations/restore epoch; ADR-0007 static content pipeline/type ids; ADR-0008 render pipeline/integer scaling; ADR-0009 presentation subscriber contract; ADR-0010 source layout/typing/lint (all Proposed, in docs/architecture/)'
const path = a => `${ROOT}/docs/architecture/adr-${a.id}-${a.slug}.md`

const AUTHOR = { type: 'object', properties: {
  adr_id: { type: 'string' }, path: { type: 'string' }, summary: { type: 'string' },
  depends_on: { type: 'array', items: { type: 'string' } },
  registry_candidates: { type: 'array', items: { type: 'object', properties: { section: { type: 'string', enum: ['state_ownership', 'interfaces', 'performance_budgets', 'api_decisions', 'forbidden_patterns', 'referenced_by_update'] }, name: { type: 'string' }, entry_yaml: { type: 'string' } }, required: ['section', 'name', 'entry_yaml'] } },
  gdd_sync: { type: 'array', items: { type: 'object', properties: { file: { type: 'string' }, old: { type: 'string' }, new: { type: 'string' } }, required: ['file', 'old', 'new'] } },
  foundation_asks: { type: 'array', items: { type: 'object', properties: { adr: { type: 'string' }, ask: { type: 'string' } }, required: ['adr', 'ask'] } },
  decisions: { type: 'array', items: { type: 'object', properties: { point: { type: 'string' }, chosen: { type: 'string' }, reason: { type: 'string' } }, required: ['point', 'chosen', 'reason'] } },
  cross_adr_assumptions: { type: 'array', items: { type: 'object', properties: { other_adr: { type: 'string' }, assumption: { type: 'string' } }, required: ['other_adr', 'assumption'] } },
  tr_coverage: { type: 'object', properties: { covered: { type: 'integer' }, partial: { type: 'integer' }, owned_elsewhere: { type: 'integer' } }, required: ['covered', 'partial', 'owned_elsewhere'] },
  open_questions: { type: 'array', items: { type: 'string' } },
}, required: ['adr_id', 'path', 'summary', 'depends_on', 'registry_candidates', 'gdd_sync', 'foundation_asks', 'decisions', 'cross_adr_assumptions', 'tr_coverage', 'open_questions'] }
const REVIEW = { type: 'object', properties: {
  adr_id: { type: 'string' }, verdict: { type: 'string' },
  findings: { type: 'array', items: { type: 'object', properties: { id: { type: 'string' }, severity: { type: 'string' }, blocking: { type: 'boolean' }, text: { type: 'string' }, amendment: { type: 'string' } }, required: ['id', 'severity', 'blocking', 'text', 'amendment'] } },
  cross_adr: { type: 'array', items: { type: 'object', properties: { adrs: { type: 'array', items: { type: 'string' } }, owner_adr: { type: 'string' }, text: { type: 'string' }, amendment: { type: 'string' } }, required: ['adrs', 'owner_adr', 'text', 'amendment'] } },
}, required: ['adr_id', 'verdict', 'findings', 'cross_adr'] }
const RULINGS = { type: 'object', properties: {
  rulings: { type: 'array', items: { type: 'object', properties: { id: { type: 'string' }, owner_adr: { type: 'string' }, other_adrs: { type: 'array', items: { type: 'string' } }, ruling: { type: 'string' }, amendment: { type: 'string' } }, required: ['id', 'owner_adr', 'other_adrs', 'ruling', 'amendment'] } },
  foundation_amendments: { type: 'array', items: { type: 'object', properties: { adr: { type: 'string' }, amendment: { type: 'string' }, reason: { type: 'string' } }, required: ['adr', 'amendment', 'reason'] } },
  rejected_findings: { type: 'array', items: { type: 'object', properties: { id: { type: 'string' }, reason: { type: 'string' } }, required: ['id', 'reason'] } },
}, required: ['rulings', 'foundation_amendments', 'rejected_findings'] }
const REVISE = { type: 'object', properties: {
  adr_id: { type: 'string' }, applied: { type: 'array', items: { type: 'string' } },
  declined: { type: 'array', items: { type: 'object', properties: { id: { type: 'string' }, reason: { type: 'string' } }, required: ['id', 'reason'] } },
  registry_candidates: AUTHOR.properties.registry_candidates, gdd_sync: AUTHOR.properties.gdd_sync, decisions: AUTHOR.properties.decisions,
  open_questions: { type: 'array', items: { type: 'string' } },
}, required: ['adr_id', 'applied', 'declined', 'registry_candidates', 'gdd_sync', 'decisions', 'open_questions'] }
const CONFIRM = { type: 'object', properties: {
  unapplied: { type: 'array', items: { type: 'string' } },
  residual: { type: 'array', items: { type: 'object', properties: { adrs: { type: 'array', items: { type: 'string' } }, severity: { type: 'string' }, text: { type: 'string' } }, required: ['adrs', 'severity', 'text'] } },
  notes: { type: 'string' },
}, required: ['unapplied', 'residual', 'notes'] }

const authorPrompt = (a, prior) => `You are authoring ONE Architecture Decision Record for the Godot 4.7.2 / GDScript game project at ${ROOT}: ADR-${a.id} "${a.title}". Write it to ${path(a)} (exact path). Status Proposed. Date 2026-10-29.

FOLLOW THE SKILL: read ${SKILL}/SKILL.md and ${SKILL}/references/1-engine-context.md, 3-gather-context.md, 4-decide.md, 5-generate.md and follow Steps 1-5 with these overrides:
- Config: review_mode full, workflow full, docs.density thorough, automation AUTONOMOUS: never call AskUserQuestion; take the recommended option and record every decision point in decisions.
- Do NOT run the engine-specialist or technical-director steps (5.5/5.6): the orchestrator reviews afterwards. End the ADR with "## Review Log" containing "pending (core-adrs workflow review)".
- Write ONLY your ADR file. Do not edit the registry, GDDs, architecture.md, tr-*.md, the traceability index, the decision log, other ADRs. Return registry candidates, GDD sync items and asks to Foundation ADRs instead. Never run git.
- Decision Makers: "Claude (author), running under modes.automation: autonomous (project.yaml); decisions logged for the user's review; the user has not yet reviewed this ADR."

SCOPE (docs/architecture/architecture.md § Required ADRs, Core table): absorbs ${a.absorbs}; decides: ${a.decides}. Notes: ${a.notes}

CONTEXT (docs are large; grep headings then bounded reads; a hook refuses whole-file reads over 40 KB):
- Requirements: grep "ADR-${a.id}" in docs/architecture/requirements-traceability.md (Planned ADR column, including rows re-tagged 2026-10-29). Your "## GDD Requirements Addressed" table must cover every one by TR-ID (registry text in docs/architecture/tr-registry.yaml); rows only loaded/checked here but decided elsewhere go in an "owned elsewhere" sub-table. Report counts in tr_coverage.
- Foundation ADRs (binding; do not contradict, build on their interfaces): ${FOUND}. Read Summary, Decision, Key Interfaces and Implementation Guidelines where your scope touches them. Exemplar for format and density: docs/architecture/adr-0007-static-content-data-pipeline-and-stable-type-ids.md. If you need a Foundation ADR changed, put it in foundation_asks; do not work around it silently.
- docs/registry/architecture.yaml (binding stances) and design/registry/entities.yaml (constants: cite names, never retype values).
- The GDDs your TR rows cite: only the cited rules (grep the rule id, e.g. "^\\*\\*LS-3", then read that range). GDD ADR-candidate notes for what you absorb (grep "${a.absorbs.split(',')[0].trim()}").
- docs/architecture/architecture.md: Required ADRs, Spikes that gate ADRs, Open Questions, System Layer Map, Data Flow, API Boundaries, Interface types still to define.
- docs/engine-reference/godot/ (VERSION.md, breaking-changes.md, deprecated-apis.md, current-best-practices.md, relevant modules/*.md). Mark every unsourced engine claim UNVERIFIED and name the spike or probe. You MAY probe small engine facts: "${GODOT}" --headless --script <file> from C:/Users/dasbl/AppData/Local/Temp/claude/adr-probes/${a.id}/ (outside the repo); record as "probed 2026-10-29".
SIBLINGS in this Core tier (do not decide their scope; reference them by number; list every assumption about them in cross_adr_assumptions):
${ALL}
${prior ? `Already drafted in earlier waves (read the parts you depend on; they are drafts, unreviewed):\n${prior}` : 'You are in wave A: the other Core ADRs are not written yet.'}
Return the structured result.`

const authored = []
for (const wave of ['A', 'B', 'C']) {
  phase('Author')
  const prior = authored.map(r => `- ${r.adr_id}: ${r.path} — ${r.summary}`).join('\n')
  const res = await parallel(ADRS.filter(a => a.wave === wave).map(a => () =>
    agent(authorPrompt(a, prior), { label: `author:ADR-${a.id}`, phase: 'Author', schema: AUTHOR, model: 'sonnet', effort: 'high' })))
  res.forEach((r, i) => { if (r) authored.push(r); else log(`AUTHOR FAILED: ADR-${ADRS.filter(a => a.wave === wave)[i].id}`) })
  log(`wave ${wave}: ${res.filter(Boolean).length} authored`)
}
const files = authored.map(r => `- ${r.adr_id}: ${r.path}`).join('\n')
const assumptions = authored.map(r => `${r.adr_id}: ${r.cross_adr_assumptions.map(x => `[${x.other_adr}] ${x.assumption}`).join(' | ') || 'none'}`).join('\n')

phase('Review')
const reviews = await parallel(authored.flatMap(r => [
  () => agent(`Review-only: do NOT edit or write any file. Act as the project's godot-specialist (${ROOT}/.claude/agents/godot-specialist.md). Validate ${r.adr_id} at ${r.path} (Proposed, Godot 4.7.2, GDScript) against ${ROOT}/docs/engine-reference/godot/. Report: idiomatic for 4.7.2; APIs or patterns deprecated, changed post-cutoff or wrong (signatures, things that will not compile: const of constructed objects, packed arrays by reference, 4.7 typed-return override rule, 4.7 packed-array element writes skip setters, Object-method name clashes such as get/set/free/call, typed collections); engine gotchas missed; plausibility of any "probed" claims. You may probe headless with "${GODOT}" --headless --script <file> from C:/Users/dasbl/AppData/Local/Temp/claude/adr-probes/review-${r.adr_id}/; if denied mark UNVERIFIED. Findings E1.. (blocking = wrong API / will not compile / incompatible) with a concrete amendment; engine contradictions with other ADRs (Core siblings: ${authored.map(x => x.adr_id).join(', ')}; Foundation ADR-0001..0010) in cross_adr with the owner_adr. Read by section (whole-file reads over 40 KB are refused).`,
    { label: `engine:${r.adr_id}`, phase: 'Review', schema: REVIEW, model: 'sonnet', effort: 'high' }),
  () => agent(`Review-only: do NOT edit or write any file. Act as the project's technical-director (${ROOT}/.claude/agents/technical-director.md) and run gate TD-ADR (${ROOT}/.claude/docs/director-gates/td-adr.md) on ${r.adr_id} at ${r.path} (Proposed, Godot 4.7.2, GDScript, review mode full). It was authored in a parallel Core tier:
${files}
Authors' assumptions about each other:
${assumptions}
Binding: Foundation ADRs ${FOUND}; docs/registry/architecture.yaml; docs/architecture/architecture.md (Layer Map, Data Flow, API Boundaries, Required ADRs, Spikes, Open Questions); its TR rows (grep "${r.adr_id}" in docs/architecture/requirements-traceability.md). Check: contradictions with Foundation ADRs and registry stances; scope overlap/gaps with Core siblings; TR traceability (every planned row addressed or explicitly owned elsewhere); right-sizing for a solo/small-team MVP; spike gating stated honestly; Key Interfaces concrete enough for stories. Verdict APPROVE / CONCERNS / REJECT; findings T1.. with severity, blocking (must change before Accept) and a concrete amendment; cross_adr items with the single owner_adr. Read by section.`,
    { label: `td:${r.adr_id}`, phase: 'Review', schema: REVIEW, model: 'opus', effort: 'high' }),
]))
const engineRev = id => reviews.filter(Boolean).find(v => v.adr_id.includes(id) && v.findings.every(f => f.id.startsWith('E')))
const all = reviews.filter(Boolean)
log(`${all.length}/${authored.length * 2} reviews returned`)

phase('Adjudicate')
const crossList = all.flatMap(v => v.cross_adr.map(c => `[from ${v.adr_id} review] owner ${c.owner_adr}; adrs ${c.adrs.join(', ')}: ${c.text} -> ${c.amendment}`))
const blockingList = all.flatMap(v => v.findings.filter(f => f.blocking).map(f => `${v.adr_id} ${f.id}: ${f.text} -> ${f.amendment}`))
const rulings = await agent(`Review-only: do NOT edit any file. Act as the project's technical-director, adjudicating the Core ADR tier (Godot 4.7.2 GDScript, ${ROOT}). Files:
${files}
Foundation (binding unless an amendment is truly needed): ${FOUND}.
Cross-ADR items raised by the per-ADR reviews:
${crossList.join('\n') || 'none'}
Blocking per-ADR findings (for context on overlaps):
${blockingList.join('\n') || 'none'}
For each cross-ADR item (merge duplicates) issue ONE ruling with an id (CT-01, CT-02...), the single owner_adr that changes, the other ADRs that must align their references, and the exact amendment text. Also look for conflicts the reviewers missed between the Core ADRs (ownership of blocks and ids, interface signatures, hook order and divisors, restore order, budgets that sum past STEP_BUDGET_MS or the frame budget, dependency cycles in Depends On). If a Foundation ADR genuinely must change, list it in foundation_amendments (the orchestrator applies those separately); prefer changing the Core ADR. Reject findings that are wrong, with reasons. Read by section (whole-file reads over 40 KB are refused).`,
  { label: 'adjudicate:TD', phase: 'Adjudicate', schema: RULINGS, model: 'opus', effort: 'high' })

phase('Revise')
const forAdr = id => {
  const own = all.filter(v => v.adr_id.includes(id)).map(v => `${v.adr_id} review verdict ${v.verdict}:\n` + v.findings.map(f => `${f.id} [${f.severity}${f.blocking ? ', BLOCKING' : ''}] ${f.text}\n  amendment: ${f.amendment}`).join('\n')).join('\n\n')
  const rl = rulings ? rulings.rulings.filter(x => x.owner_adr.includes(id) || x.other_adrs.some(o => o.includes(id))).map(x => `${x.id} owner ${x.owner_adr} (align: ${x.other_adrs.join(', ')}): ${x.ruling}\n  amendment: ${x.amendment}`).join('\n') : 'adjudication unavailable'
  const rej = rulings ? rulings.rejected_findings.map(x => `${x.id}: ${x.reason}`).join('\n') : ''
  return `${own}\n\nCROSS-ADR RULINGS (binding):\n${rl || 'none'}\n\nREJECTED FINDINGS (do not apply):\n${rej || 'none'}`
}
const revised = (await parallel(authored.map(r => () => {
  const id = (r.adr_id.match(/\d{4}/) || [''])[0]
  return agent(`You are revising ${r.adr_id} at ${r.path} (project ${ROOT}, Godot 4.7.2 GDScript) after per-ADR engine and TD-ADR reviews and a cross-ADR adjudication of the Core tier. Autonomous mode: "Revise flagged items". Apply every BLOCKING finding and every ruling you own; align your references to rulings owned by other ADRs without taking over their decisions; apply non-blocking findings unless clearly wrong (decline with a reason). Do not apply rejected findings. Edit only this file (grep and bounded reads; whole-file reads over 40 KB are refused). Keep Status Proposed. Replace the pending Review Log line with a Review Log dated 2026-10-29 listing each finding/ruling id and what was done. Never run git; do not edit registries, GDDs or other ADRs.

${forAdr(id)}

Your original registry candidates (return the final set matching the revised ADR): ${JSON.stringify(r.registry_candidates)}
Your original GDD sync items (return the final set): ${JSON.stringify(r.gdd_sync)}`,
    { label: `revise:${r.adr_id}`, phase: 'Revise', schema: REVISE, model: 'sonnet', effort: 'high' })
}))).filter(Boolean)

phase('Confirm')
const confirm = await agent(`Review-only: do NOT edit any file. The Core ADRs were just revised:
${files}
(1) For each blocking finding and ruling below, is it applied in the current text? List unapplied ones (with ADR id). (2) Residual inconsistencies between the Core ADRs and against Foundation ADR-0001..0010 and docs/registry/architecture.yaml (interface names and signatures, block and id ownership, hook order, restore order, budgets, Depends On / Enables symmetry). Quote concretely. Read by section.
Blocking findings:
${blockingList.join('\n') || 'none'}
Rulings:
${rulings ? rulings.rulings.map(x => `${x.id} owner ${x.owner_adr}: ${x.amendment}`).join('\n') : 'none'}`,
  { label: 'confirm:core', phase: 'Confirm', schema: CONFIRM, model: 'sonnet', effort: 'high' })

phase('Registry')
const registryReport = await agent(`You are the single serial writer for two files in ${ROOT}. Autonomous mode, standing instruction to apply registry updates after review.
(1) Append these registry candidates to docs/registry/architecture.yaml following the file's header LAYOUT rules and each section's existing entry shape; append after the last entry of the section; for referenced_by_update add the ADR path to the named entry's referenced_by only; merge duplicates (both ADRs in referenced_by) and report them; never modify other fields. Then run bash .claude/scripts/registry.sh validate (all 0) and python -c "import yaml;yaml.safe_load(open('docs/registry/architecture.yaml',encoding='utf-8'))"; fix any layout error you introduced.
Candidates: ${JSON.stringify(revised.map(r => ({ adr: r.adr_id, items: r.registry_candidates })))}
(2) Append to production/session-logs/decision-log.md (append only) one section per ADR: "## 2026-10-29 — architecture-decision (ADR-NNNN, core-adrs workflow)" with each decision as **Decision point:** / **Options considered:** / **Chosen:** / **Reason:** / **Category:** architecture, plus one entry for the review ("Revise flagged items"; applied and declined ids) and one for the registry update.
Decisions: ${JSON.stringify([...authored.map(r => ({ adr: r.adr_id, stage: 'author', items: r.decisions })), ...revised.map(r => ({ adr: r.adr_id, stage: 'revise', items: r.decisions, applied: r.applied, declined: r.declined }))])}
Edit no other file. Never run git. Return a short plain-text report.`,
  { label: 'registry+log', phase: 'Registry', model: 'sonnet', effort: 'medium' })

return {
  authored: authored.map(r => ({ adr: r.adr_id, path: r.path, summary: r.summary, depends_on: r.depends_on, tr_coverage: r.tr_coverage, foundation_asks: r.foundation_asks })),
  verdicts: all.map(v => ({ adr: v.adr_id, verdict: v.verdict, blocking: v.findings.filter(f => f.blocking).length, total: v.findings.length })),
  rulings,
  revised: revised.map(r => ({ adr: r.adr_id, applied: r.applied.length, declined: r.declined, open_questions: r.open_questions })),
  gdd_sync: revised.map(r => ({ adr: r.adr_id, items: r.gdd_sync })),
  confirm,
  registryReport,
}

