input.command:
S="C:/Users/dasbl/AppData/Local/Temp/claude/D--the-synaptic-sea-2d/a5c30614-4e6e-4b6b-a781-54ec94879f80/scratchpad/ar"; mkdir -p $S/csync && PYTHONIOENCODING=utf-8 python - "$S" <<'EOF'
import json,sys,re,os,collections
S=sys.argv[1]; g=json.load(open(S+'/core/gdd-sync.json',encoding='utf-8'))
pk=collections.defaultdict(list); unrouted=[]
n=0
for blk in g:
    for it in blk['items']:
        n+=1
        paths=re.findall(r'((?:design|docs|tests|assets)/[\w/.\-]+\.(?:md|yaml|json))',it['file'])
        for m in re.findall(r'\b([a-z0-9\-]+\.md)\b',it['file']):
            if not any(p.endswith(m) for p in paths) and os.path.exists('design/gdd/'+m): paths.append('design/gdd/'+m)
        if not paths: unrouted.append(it['file']); continue
        for p in paths: pk[p].append(dict(id=f"C{n}",adr=blk['adr'],where=it['file'],old=it['old'],new=it['new']))
pk['design/gdd/life-support-graph.md'].append(dict(id='R11',adr='ADR-0012',where='LS-9 RNG counter',old='(step_no << 20)',new='counter (step_no << 26) | rng_subject(kind, id) per ADR-0012 § 8.2 (26-bit subject key)'))
pk['docs/architecture/tr-baseline.md'].append(dict(id='R3',adr='ADR-0015',where='TR-shipbody-030',old='seat_bindings() -> [(seat, actor_id)]',new='seat_bindings() -> [(player_id, actor_id)] (at MVP seat == PlayerId; ADR-0016 § 6.2)'))
print('items',n,'files',len(pk),'unrouted',len(unrouted)); [print(' U',u[:150]) for u in unrouted]
args=[]
for i,(f,items) in enumerate(sorted(pk.items())):
    fn=f"{S}/csync/p{i:02d}.json"; json.dump(dict(file=f,items=items,contradictions=[],extra=[]),open(fn,'w',encoding='utf-8'),indent=1,ensure_ascii=False)
    args.append(dict(file=f,packet=fn)); print(f,len(items),os.path.exists(f))
json.dump(args,open(S+'/csync/args.json','w'))
EOF

